questionvariables.text:
/*stat 1*/
aa:rand(2)+2;
bb:rand(3)+3;
cc:rand(6)+6;
dd:rand(5)+4;
ee:rand(3)+2;
quest_percent1:rand([20,40,60,80]);
quest_percent2:rand([40,60,80]);
/*model answer*/
sol1:aa;
sol2:aa+bb;
sol3:aa+bb+cc;
sol4:aa+bb+cc+dd;
ta1:if quest_percent1=20 then sol1 else if quest_percent1=40 then sol2 else if quest_percent1=60 then sol3 else if quest_percent1=80 then sol4;
sol5:cc+dd+ee;
sol6:dd+ee;
sol7:ee;
ta2:if quest_percent2=40 then sol5 else if quest_percent2=60 then sol6 else if quest_percent2=80 then sol7;
